  stats:[{v:"125+ h",l:{ro:"formare",en:"training"}},{v:"500 h",l:{ro:"practică (450 plătite)",en:"practice (450 paid)"}},{v:"3 ani",l:{ro:"valabilitate",en:"validity"}}],
