 {t:"RPL / Onboarding / Integrare",d:{ro:"Recunoașterea învățării anterioare: programe care îți echivalează ce ai făcut (inclusiv ANC) și îți dau certificatul de program acreditat.",en:"Recognition of prior learning: programs that credit what you've done (including ANC) and issue the accredited program certificate."}},
 {t:"COR",d:{ro:"Clasificarea Ocupațiilor din România. Coach = 242412, Formator = 242401, Mentor (învățământ) = 235902.",en:"Romanian Occupation Classification. Coach = 242412, Trainer = 242401, Mentor (education) = 235902."}},
 {t:"ANC / MMSS / ME / APIS",d:{ro:"Autoritatea Națională pentru Calificări (standardele), Ministerul Muncii și Solidarității Sociale + Ministerul Educației (certificatele), Agențiile pentru Plăți și Inspecție Socială (secretariatele comisiilor de autorizare).",en:"National Qualifications Authority (standards), Labour and Education ministries (certificates), Payment & Social Inspection Agencies (authorisation commission secretariats)."}},
 {t:"ESS",d:{ro:"Education Search Service — directorul oficial ICF în care verifici dacă un program este chiar acreditat.",en:"ICF's official directory to verify whether a program is really accredited."}},
 {t:"Pearson VUE / OnVUE",d:{ro:"Partenerul care administrează examenele ICF — în centru de testare sau online cu proctoring video.",en:"ICF's exam administrator — test center or online with video proctoring."}},
 {t:"Exchange of value",d:{ro:"Orice contraprestație (bani, barter, abonament) califică ora drept „plătită” la ICF.",en:"Any consideration (money, barter, subscription) qualifies a session as 'paid' at ICF."}},
 {t:"Global Code of Ethics",d:{ro:"Cod etic comun ICF + EMCC + Association for Coaching; 3 ore de etică sunt obligatorii la reînnoirea ICF.",en:"Shared ethics code of ICF + EMCC + Association for Coaching; 3 ethics hours are mandatory for ICF renewal."}}
